// One-off corpus generation script. Draws real selectable text onto a PDF
// page (page.drawText), producing a native-text PDF — distinct from the
// "scanned" (image-only) PDFs generated by generate-scanned-pdf-cvs.mjs.
import { PDFDocument, StandardFonts, rgb } from "pdf-lib";
import fs from "node:fs/promises";
import path from "node:path";

async function buildCvPdf(lines) {
  const pdf = await PDFDocument.create();
  const font = await pdf.embedFont(StandardFonts.Helvetica);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
  let page = pdf.addPage([612, 792]); // US Letter
  const margin = 54;
  let y = 792 - margin;
  const maxWidth = 612 - margin * 2;

  function wrap(text, size, useFont) {
    const words = text.split(" ");
    const out = [];
    let line = "";
    for (const w of words) {
      const trial = line ? line + " " + w : w;
      if (useFont.widthOfTextAtSize(trial, size) > maxWidth) {
        out.push(line);
        line = w;
      } else {
        line = trial;
      }
    }
    if (line) out.push(line);
    return out;
  }

  function ensureSpace(needed) {
    if (y - needed < margin) {
      page = pdf.addPage([612, 792]);
      y = 792 - margin;
    }
  }

  for (const l of lines) {
    const size = l.size ?? 11;
    const useFont = l.bold ? bold : font;
    const wrapped = wrap(l.text, size, useFont);
    for (const w of wrapped) {
      ensureSpace(size + 4);
      page.drawText(w, { x: margin, y, size, font: useFont, color: rgb(0, 0, 0) });
      y -= size + 4;
    }
    y -= l.gapAfter ?? 2;
  }

  return pdf.save();
}

